/* 竹间 — a private, static learning studio. All progress stays on this origin. */
(()=>{'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], C=window.COURSE||{lessons:[]}, L=Learn;
let storage;try{storage=window.localStorage;}catch{storage={getItem(){throw Error('Storage unavailable')},setItem(){throw Error('Storage unavailable')}};}
let state=L.load(storage),route,practice=null,session=null,writer=null,recorder=null,stream=null,recordUrl=null,recognizer=null,db=null,bookUrl=null,bookKind='workbook',bookPage=13,writeChar='',drawing=false,drawPoints=[],drawHistory=[],voiceList=[],audioHeard=false;
let saved=!state.loadError;const initialLoadError=state.loadError;delete state.loadError;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tr=(en,ru)=>state.settings.lang==='ru'?ru:en;
const bi=x=>typeof x==='string'?x:(x?.[state.settings.lang]||x?.en||'');
const text=x=>esc(bi(x));
const date=at=>new Date(at).toLocaleDateString(state.settings.lang==='ru'?'ru-RU':'en-GB',{day:'numeric',month:'short'});
const icons={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',book:'<path d="M12 5C8 2 3 4 3 4v15s5-2 9 1c4-3 9-1 9-1V4s-5-2-9 1zM12 5v15"/>',practice:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M5 8a8 8 0 0 1 14-3l1 2M4 17l1 2a8 8 0 0 0 14-3"/>',pen:'<path d="m4 16-1 5 5-1L21 7l-5-5zM13 5l6 6M4 16l4 4"/>',homework:'<path d="M6 3h12v19H6zM9 7h6M9 11h6M9 15h3"/>',chart:'<path d="M3 3v18h18M7 16v-5M12 16V6M17 16v-8"/>',library:'<path d="M4 4h4v16H4zM10 4h4v16h-4zM16 5l3-1 4 15-3 1z"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16M8 3v6M16 9v6M10 15v6"/>',audio:'<path d="m3 9 4 0 5-4v14l-5-4H3zM16 8a6 6 0 0 1 0 8M19 5a10 10 0 0 1 0 14"/>',mic:'<rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',leaf:'<path d="M20 3C5 2 1 13 8 18c7 4 14-4 12-15zM5 21l10-12"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.book}</svg>`;
const btn=(label,action,opts='')=>`<button class="btn ${opts}" data-action="${action}">${label}</button>`;
const link=(label,url)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label}</a>`;
const skillName=s=>({vocabulary:tr('Vocabulary','Слова'),grammar:tr('Grammar','Грамматика'),reading:tr('Reading','Чтение'),listening:tr('Listening','Аудирование'),speaking:tr('Speaking','Речь'),writing:tr('Writing','Письмо'),homework:tr('Homework','Домашнее задание'),phonetics:tr('Phonetics','Фонетика')}[s]||s);
const modes={cards:['Recall cards','Карточки','practice','Retrieve the meaning before turning the card.','Вспомните значение до переворота карточки.'],recall:['Active recall','Вспомнить и написать','pen','Produce a word from its meaning.','Напишите слово по его значению.'],grammar:['Grammar check','Проверка грамматики','book','Make a choice, then explore the explanation.','Выберите ответ и разберите объяснение.'],sentence:['Build a sentence','Собрать предложение','homework','Put the Chinese chunks into order.','Расположите части китайской фразы по порядку.'],listening:['Listen & understand','Услышать и понять','audio','Hear a word without seeing its characters.','Послушайте слово, не видя иероглифов.'],reading:['Read in context','Чтение в контексте','book','Read a short text and find the meaning.','Прочитайте небольшой текст и найдите смысл.'],speaking:['Listen & speak','Слушать и говорить','mic','Shadow a phrase, record, and compare.','Повторите фразу, запишите речь и сравните.']};
function persist(){saved=L.save(storage,state);if(!saved)toast(tr('Storage is full or unavailable. Export a backup now.','Хранилище заполнено или недоступно. Экспортируйте резервную копию.'));}
function log(e){state.events.push({at:Date.now(),...e});persist();}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function nav(hash){if(location.hash===hash){route=parseRoute();render();}else location.hash=hash;}
function parseRoute(){const [page='home',id='',tab='understand']=location.hash.replace(/^#/,'').split('/');return {page,id,tab};}
function currentLesson(){return C.lessons.find(l=>l.id===Number(route.id))||C.lessons.find(l=>!state.completed.includes(l.id))||C.lessons[0];}
function lessonById(id){return C.lessons.find(l=>l.id===Number(id))||C.lessons[0];}
function startLesson(id){if(!state.started.includes(id)){state.started.push(id);persist();}}
function allVocab(){return C.lessons.flatMap(l=>l.vocab.map(v=>({...v,lesson:l.id})));}
function num(value){return value.toLocaleString(state.settings.lang==='ru'?'ru-RU':'en-US');}
function pct(value){return value===null?'—':Math.round(value*100)+'%';}
function title(en,ru,subEn,subRu,action=''){return `<div class="page-heading"><div><p class="eyebrow">${tr('HELLO CHINESE · YOUR LEARNING STUDIO','HELLO CHINESE · ВАША УЧЕБНАЯ СТУДИЯ')}</p><h1>${tr(en,ru)}</h1><p class="subtle no-margin">${tr(subEn,subRu)}</p></div>${action}</div>`;}
function shell(content){const page=route.page==='lesson'?'course':route.page;const items=[['home','home','Today','Сегодня'],['course','book','Learning path','Курс'],['practice','practice','Practice','Практика'],['writing','pen','Writing studio','Мастерская письма'],['homework','homework','Homework','Домашние задания'],['analytics','chart','Your progress','Ваш прогресс'],['library','library','Library & sources','Материалы'],['settings','settings','Settings & backup','Настройки и копии']];
document.documentElement.lang=state.settings.lang;document.title=`竹间 · ${items.find(i=>i[0]===page)?.[state.settings.lang==='ru'?3:2]||tr('Chinese','Китайский')}`;
$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#home"><span class="brand-mark" lang="zh-Hans">竹</span><span><strong>竹间 ZHÚJIĀN</strong><small>${tr('A LITTLE CHINESE, EVERY DAY','КИТАЙСКИЙ КАЖДЫЙ ДЕНЬ')}</small></span></a><nav class="nav" aria-label="${tr('Main navigation','Главное меню')}">${items.map(([p,i,en,ru])=>`<button data-go="#${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${icon(i)}${tr(en,ru)}</button>`).join('')}</nav><div class="sidebar-foot">${icon('leaf')}<strong>${tr('Small steps. Lasting learning.','Маленькие шаги. Прочные знания.')}</strong>${tr('14 classes · English / Русский','14 занятий · English / Русский')}<div class="section-line">${tr('Your progress belongs to you.','Ваш прогресс принадлежит вам.')}<br>${tr('Saved on this device.','Сохраняется на этом устройстве.')}</div></div></aside><div class="main-wrap"><header class="topbar"><div class="breadcrumb"><span class="mobile-brand">竹间</span>${tr('My studio','Моя студия')} <span aria-hidden="true">/</span> ${items.find(i=>i[0]===page)?.[state.settings.lang==='ru'?3:2]||tr('Foundations','Основы')}</div><div class="top-actions">${Translator.toolbar()}<span class="local-status"><span class="dot"></span>${saved?tr('Saved on device','Сохранено локально'):tr('Backup needed','Нужна копия')}</span><div class="lang-switch" aria-label="${tr('Interface language','Язык интерфейса')}"><button data-lang="en" class="${state.settings.lang==='en'?'active':''}" aria-pressed="${state.settings.lang==='en'}">EN</button><button data-lang="ru" class="${state.settings.lang==='ru'?'active':''}" aria-pressed="${state.settings.lang==='ru'}">RU</button></div></div></header><main id="main" tabindex="-1">${!saved?`<div class="notice">${tr('Progress cannot currently be saved. Keep this tab open and export a backup in Settings.','Сейчас прогресс не сохраняется. Не закрывайте вкладку и экспортируйте копию в настройках.')}</div>`:''}${content}</main></div></div>`;
}
function render(){route=parseRoute();stopCapture();writer?.cancelQuiz();if(route.page!=='practice')practice=null;let content='';switch(route.page){case'course':content=coursePage();break;case'lesson':content=lessonPage();break;case'practice':content=practicePage();break;case'writing':content=writingPage();break;case'homework':content=homeworkPage();break;case'analytics':content=analyticsPage()+Studio.analytics();break;case'library':content=libraryPage();break;case'settings':content=settingsPage();break;case'phonetics':content=Studio.phonetics();break;default:content=Studio.nextReview()+homePage();}shell(content);Studio.mount();if(route.page==='writing')mountWriter();if(route.page==='library'&&bookUrl)mountBook();updateVoices();}
function recommendation(){const rec=L.recommend(state,C.lessons);let reason=rec.reason==='due'?tr(`${rec.count} cards are ready for spaced review.`,`${rec.count} карточек пора повторить.`):rec.reason==='weak'?tr(`${skillName(rec.skill)}: ${rec.k}/${rec.n} recent checks on a difficult item. Revisit it in context.`,`${skillName(rec.skill)}: ${rec.k}/${rec.n} проверок сложного задания. Повторите его в контексте.`):rec.reason==='new'?tr('Build connections with the words in your current class.','Закрепите связи между словами текущего урока.'):tr('Continue through your classes in their original order.','Продолжайте занятия в исходном порядке.');return {...rec,reasonText:reason};}
function homePage(){const rec=recommendation(),l=lessonById(rec.lesson),vocab=allVocab(),due=L.dueItems(state,vocab).filter(v=>state.cards[v.id]),today=state.events.filter(e=>L.dateKey(e.at)===L.dateKey()),s=L.stats(state.events),next=C.lessons.find(l=>!state.completed.includes(l.id))||C.lessons[0];return `${title('Make room for Chinese.','Немного места для китайского.','One focused session. A little more confidence.','Одно вдумчивое занятие. Чуть больше уверенности.',`<span class="tag">${new Date().toLocaleDateString(state.settings.lang==='ru'?'ru-RU':'en-GB',{weekday:'long',day:'numeric',month:'long'})}</span>`)}<div class="grid2 home-grid"><section class="hero"><div><span class="eyebrow">${tr('YOUR NEXT SMALL STEP','ВАШ СЛЕДУЮЩИЙ ШАГ')}</span><h2>${text(l.title)}</h2><p>${rec.reasonText}</p>${btn(tr('Start my session','Начать занятие')+icon('arrow'),'daily','primary')}<span class="small muted" style="display:inline-block;margin-left:10px">${icon('clock')} ${state.settings.goal} ${tr('min target','мин · цель')}</span></div><div class="hero-art" aria-hidden="true"><div class="circle">学</div><span class="seal">温故知新</span></div></section><section class="card"><div class="row between"><h3 class="no-margin">${tr('A balanced practice','Разные стороны языка')}</h3>${icon('leaf')}</div><p class="small muted m-t">${tr('Recall → understand → use. Your plan adapts to due reviews and checked mistakes.','Вспомнить → понять → применить. План учитывает повторения и ошибки в проверках.')}</p>${['vocabulary','listening','grammar'].map(k=>skillLine(k)).join('')}<p class="tiny muted no-margin">${tr('Checked responses only · no activity yet means no estimate.','Только проверенные ответы · без данных оценки нет.')}</p></section></div><div class="grid4 section">${metric(L.streak(state.events),tr('Day streak','Дней подряд'),tr('Any logged practice','Любая записанная практика'))}${metric(due.length,tr('Cards due','Пора повторить'),tr('Review before new cards','Повторите перед новыми'))}${metric(state.completed.length+'/14',tr('Classes studied','Пройдено занятий'),tr('Marked by you','Отмечено вами'))}${metric(today.length,tr('Activities today','Действий сегодня'),tr('Every useful attempt counts','Попытки тоже важны'))}</div><section class="section"><div class="section-head"><h2>${tr('Your learning path','Ваш учебный маршрут')}</h2><a href="#course" class="small">${tr('All 14 classes','Все 14 занятий')} →</a></div><div class="path">${C.lessons.slice(Math.max(0,next.id-1),Math.max(3,next.id+2)).slice(0,3).map(lessonCard).join('')}</div></section><section class="grid2 section"><div class="card"><p class="eyebrow">${tr('BUILD THE FOUNDATIONS','ЗАЛОЖИТЕ ОСНОВУ')}</p><h2>${tr('Hear the shape of a word.','Услышьте форму слова.')}</h2><p class="small muted">${tr('Tones change meaning. Explore the sound system, tone changes, and pinyin spelling before lesson 1—or revisit any time.','Тон меняет значение. Разберите звуки, изменения тонов и запись пиньиня перед уроком 1 или вернитесь к ним позже.')}</p><a class="btn" href="#phonetics">${tr('Explore phonetics','Разобрать фонетику')} →</a></div><div class="card"><p class="eyebrow">${tr('RECALL FIRST, REVEAL SECOND','СНАЧАЛА ВСПОМНИТЕ, ПОТОМ ОТКРОЙТЕ')}</p><h2>${tr('Let forgetting guide your review.','Пусть забывание направляет повторение.')}</h2><p class="small muted">${tr('A mistake is a useful signal. Try from memory, read the feedback, then come back after a delay. A mind map supports connections; retrieval checks whether you remember.','Ошибка — полезный сигнал. Попробуйте вспомнить, прочитайте объяснение и вернитесь через время. Карта связей помогает пониманию; воспроизведение проверяет память.')}</p><a class="small" href="#library">${tr('Why the studio works this way','Почему студия устроена так')} →</a></div></section>`;}
function metric(n,label,hint){return `<div class="card metric"><span class="number">${n}</span><span class="label">${label}</span><div class="hint">${hint}</div></div>`;}
function skillLine(k){const s=L.stats(state.events,k);return `<div class="skill-line"><span>${skillName(k)}</span><div class="track"><span style="width:${s.rate===null?0:s.rate*100}%"></span></div><span class="muted" title="n=${s.n}">${pct(s.rate)} <span class="tiny">(${s.n})</span></span></div>`;}
function lessonCard(l){const done=state.completed.includes(l.id),started=state.started.includes(l.id);return `<button class="lesson-card ${started&&!done?'current':''}" data-go="#lesson/${l.id}"><div class="row between"><span class="lesson-number">${tr('CLASS','УРОК')} ${String(l.id).padStart(2,'0')}</span>${done?`<span class="tag green">${tr('Studied','Пройден')}</span>`:started?`<span class="tag coral">${tr('In progress','В процессе')}</span>`:''}</div><span class="chinese" lang="zh-Hans">${esc(l.titleZh)}</span><h3>${text(l.title)}</h3><div class="row between mini-meta"><span>${l.vocab.length} ${tr('words','слов')} · ${l.grammar.length} ${tr('patterns','конструкций')}</span><span>↗</span></div></button>`;}
function coursePage(){return `${title('A path that follows your class.','Курс в порядке ваших занятий.','Start with sounds, then work through lessons 1–14. Every lesson stays accessible.','Начните со звуков, затем переходите к урокам 1–14. Все уроки доступны.')}<a class="card row between" style="text-decoration:none;margin-bottom:22px" href="#phonetics"><span class="row">${icon('audio')}<span><strong>${tr('00 · Sounds & pinyin','00 · Звуки и пиньинь')}</strong><br><span class="small muted">${tr('Tones, initials, finals, spelling & tone changes','Тоны, инициали, финали, правила записи и изменения тонов')}</span></span></span><span>→</span></a><div class="path">${C.lessons.map(lessonCard).join('')}</div><div class="notice m-t">${tr('The books also contain lesson 15. Its source pages are indexed in the Library as an extension; the taught path follows the 14 lesson decks you supplied.','В книгах есть и урок 15. Его страницы указаны в библиотеке как продолжение; основной курс следует вашим 14 презентациям.')}</div>`;}
function lessonPage(){const l=currentLesson();startLesson(l.id);let tab=route.tab;const tabs=[['understand','Understand','Разобраться'],['words','Words & connections','Слова и связи'],['read','Read & listen','Читать и слушать'],['play','Playground','Интерактив'],['resources','Go deeper','Глубже']];let body='';
if(tab==='words'){body=`<div class="section-head"><h2>${tr('Words in this class','Слова урока')}</h2><button class="btn small" data-practice="cards" data-lesson="${l.id}">${tr('Practice these words','Повторить слова')}</button></div><div class="vocab-grid">${l.vocab.map(v=>`<div class="vocab-card"><div class="row between"><span class="zh" lang="zh-Hans">${esc(v.hanzi)}</span>${speakButton(v.hanzi)}</div>${state.settings.pinyin?`<span class="pinyin">${esc(v.pinyin)}</span>`:''}<p>${esc(v[state.settings.lang])}</p>${v.mnemonic?`<p class="mnemonic">${text(v.mnemonic)}</p>`:''}</div>`).join('')}</div><section class="section"><h2>${tr('A map of useful connections','Карта полезных связей')}</h2><p class="small muted">${tr('Choose a branch, explain its pattern aloud, then close the notes and make your own sentence. Memory cues are learning aids, not historical etymology.','Выберите ветку, объясните конструкцию вслух, закройте заметки и составьте свою фразу. Подсказки для памяти — учебные ассоциации, не этимология.')}</p><div class="mindmap"><div class="mind-center"><div class="zh" lang="zh-Hans">${esc(l.titleZh)}</div>${text(l.title)}</div>${l.mindMap?.branches?l.mindMap.branches.map(b=>`<div class="mind-branch"><h3>${text(b.label)}</h3><div class="row wrap">${b.items.map(ch=>`<button class="token" data-speak="${esc(ch)}">${esc(ch)}</button>`).join('')}</div></div>`).join(''):''}</div></section>`;}
else if(tab==='read'){const r=l.reading;body=`${Studio.reading(l)}<section class="section"><h2>${tr('Say something useful','Скажите что-нибудь полезное')}</h2>${l.sentences.map(s=>`<div class="card" style="margin-bottom:13px"><div class="row between"><span class="zh" lang="zh-Hans">${esc(s.zh)}</span>${speakButton(s.zh)}</div>${true?`<p class="pinyin">${esc(s.pinyin)}</p>`:''}<p class="small no-margin">${esc(s[state.settings.lang])}</p></div>`).join('')}<button class="btn" data-practice="speaking" data-lesson="${l.id}">${tr('Open the speaking studio','Открыть речевую практику')}</button></section>`;}
else if(tab==='play'){body=Labs.html(l.id);}
else if(tab==='resources'){body=Studio.deep(l)+sourceReference(l);}
else{body=`<div class="grid2"><div class="card"><h2>${tr('After this class, try to…','После урока попробуйте…')}</h2><ul>${l.objectives.map(o=>`<li>${text(o)}</li>`).join('')}</ul><p class="small muted no-margin">${text(l.summary)}</p></div><div class="card"><p class="eyebrow">${tr('MAKE IT YOURS','ПРИМЕНИТЕ К СЕБЕ')}</p><h2>${tr('Understand → retrieve → use','Понять → вспомнить → применить')}</h2><p class="small muted">${tr('Read one explanation. Hide it and reconstruct the pattern. Then say a sentence about your life. Return tomorrow without the notes.','Прочитайте одно объяснение. Скройте его и восстановите конструкцию. Затем скажите фразу о своей жизни. Завтра вернитесь к ней без заметок.')}</p><div class="row wrap"><button class="btn primary" data-practice="grammar" data-lesson="${l.id}">${tr('Try a grammar check','Проверить грамматику')}</button><a class="btn" href="#homework/${l.id}">${tr('Homework','Домашнее задание')}</a></div></div></div><div class="stack section">${l.grammar.map((g,i)=>Studio.construction(l,i,g)).join('')}</div>`;}
return `<div class="page-heading"><div><p class="eyebrow">${tr('CLASS','УРОК')} ${String(l.id).padStart(2,'0')} / 14</p><h1 class="lesson-title-zh" lang="zh-Hans">${esc(l.titleZh)}</h1><p class="pinyin">${esc(l.titlePinyin)}</p><p class="subtle no-margin">${text(l.title)}</p></div><button class="btn ${state.completed.includes(l.id)?'':'primary'}" data-complete="${l.id}">${icon('check')}${state.completed.includes(l.id)?tr('Studied · undo','Пройден · отменить'):tr('Mark as studied','Отметить пройденным')}</button></div><div class="tabs" aria-label="${tr('Lesson sections','Разделы урока')}">${tabs.map(([id,en,ru])=>`<button class="${tab===id?'active':''}" data-go="#lesson/${l.id}/${id}">${tr(en,ru)}</button>`).join('')}</div>${body}<div class="section row between"><a class="btn" href="${l.id===1?'#phonetics':'#lesson/'+(l.id-1)}">← ${tr('Previous','Назад')}</a><span class="tiny muted">${tr('Studied is a personal checklist, not a proficiency score.','Отметка «пройден» — ваш список, а не оценка владения языком.')}</span>${l.id<14?`<a class="btn" href="#lesson/${l.id+1}">${tr('Next class','Следующий урок')} →</a>`:''}</div>`;
}
function speakButton(zh){return `<button class="icon-btn" data-speak="${esc(zh)}" aria-label="${tr('Listen to','Послушать')} ${esc(zh)}">${icon('audio')}</button>`;}
function sourceReference(l){const b=C.bookMap?.find(b=>b.lesson===l.id);return `<div class="card m-t"><h3>${tr('Source map','Карта источников')}</h3><p class="small">${tr('Class presentation','Презентация урока')} ${l.id} · ${b?`Hello Chinese I: PDF ${b.pdfStart}–${b.pdfEnd}, ${tr('printed','печатные')} ${b.printedStart}–${b.printedEnd}`:''}</p><p class="small muted">${tr('Examples and explanations in this studio are adapted or newly authored. Open your original book locally for exact page layout and all source exercises.','Примеры и объяснения в студии адаптированы или созданы для практики. Откройте свою книгу локально для исходной вёрстки и всех упражнений.')}</p><a href="#library" class="btn small">${tr('Open source library','Открыть библиотеку')}</a></div>`;}
function resourceHTML(r){return `<a class="resource" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${text(r.title||r.name)}<span>${text(r.why||r.description||r.note||r.use)}</span></a>`;}
function shuffle(items){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function lessonSelect(id,name='practice-lesson'){return `<select id="${name}" aria-label="${tr('Choose a class','Выберите урок')}">${C.lessons.map(l=>`<option value="${l.id}" ${l.id===Number(id)?'selected':''}>${l.id}. ${text(l.title)}</option>`).join('')}</select>`;}
function makePractice(mode,id){const l=lessonById(id);startLesson(l.id);const cap=session?Math.max(2,Math.round(state.settings.goal/3)):10;
let items=mode==='grammar'?l.quiz:mode==='sentence'||mode==='speaking'?l.sentences:mode==='reading'?[l.reading]:l.vocab;
items=items.map((x,i)=>({...x,originalIndex:i,id:x.id||`${mode}-${l.id}-${i}`,lesson:l.id}));
if(mode==='cards'){const due=L.dueItems(state,items);items=due.length?due:items;}
else if(mode==='speaking'){items=Studio.rankSelf(items,'speaking');}
else if(mode!=='reading'&&mode!=='speaking'){const mistakes=new Set(L.weak(state.events).map(x=>x.item));items=shuffle(items).sort((a,b)=>Number(mistakes.has(b.id))-Number(mistakes.has(a.id)));}
practice={mode,lesson:l.id,items:items.slice(0,mode==='speaking'?3:cap),i:0,revealed:false,answered:false,result:null,answerMode:'hanzi',correct:0,checked:0,rated:0,selected:[],started:Date.now()};
prepQuestion();
}
function prepQuestion(){if(!practice)return;practice.revealed=false;practice.answered=false;practice.result=null;practice.selected=[];audioHeard=false;const item=practice.items[practice.i];if(!item)return;
if(!item.shuffled&&['grammar','reading'].includes(practice.mode)){const field=practice.mode==='grammar'?'choices':'options',options=shuffle(item[field].map((value,index)=>({value,index})));item[field]=options.map(x=>x.value);item.answer=options.findIndex(x=>x.index===item.answer);item.shuffled=true;}
if(practice.mode==='listening'){const choices=[item,...shuffle(C.lessons.flatMap(l=>l.vocab)).filter(v=>v.hanzi!==item.hanzi&&v.en!==item.en&&v.ru!==item.ru).slice(0,3)];practice.choices=shuffle(choices);}
if(practice.mode==='sentence')practice.tokens=shuffle((item.tokens||[]).map((zh,i)=>({zh,i})));
}
function startPractice(mode,id,keepSession=false){if(!keepSession)session=null;makePractice(mode,id);if(location.hash!==`#practice/${id}/${mode}`)location.hash=`#practice/${id}/${mode}`;else render();}
function sessionStrip(){return session?`<div class="session-plan" aria-label="${tr('Session plan','План занятия')}">${session.steps.map((s,i)=>`<span class="session-step ${i===session.i?'active':i<session.i?'done':''}">${i<session.i?'✓ ':''}${s==='writing'?skillName('writing'):tr(modes[s]?.[0]||s,modes[s]?.[1]||s)}</span>`).join('')}</div>`:'';}
function daily(){const r=recommendation();startLesson(r.lesson);const steps=state.settings.goal===5?['cards','grammar','speaking']:state.settings.goal===10?['cards','grammar','listening','speaking']:['cards','grammar','reading','listening','writing','speaking'];session={lesson:r.lesson,steps,i:0,started:Date.now()};startPractice(steps[0],r.lesson,true);}
function advanceSession(){if(!session)return nav('#home');session.i++;const mode=session.steps[session.i];if(!mode){session=null;toast(tr('Session complete. Come back after a break.','Занятие завершено. Вернитесь после перерыва.'));nav('#analytics');return;}if(mode==='writing')nav('#writing/'+session.lesson);else startPractice(mode,session.lesson,true);}
function practicePage(){if(!route.id||!modes[route.tab])return `${title('Practice with a purpose.','Практика со смыслом.','Choose a class and the skill you want to strengthen.','Выберите урок и навык, который хотите укрепить.')}<div class="controls"><label for="practice-lesson">${tr('Class','Урок')}</label>${lessonSelect(currentLesson().id)}</div><div class="mode-grid">${Object.entries(modes).map(([id,m])=>`<button class="mode-card" data-mode="${id}">${icon(m[2])}<h3>${tr(m[0],m[1])}</h3><p>${tr(m[3],m[4])}</p></button>`).join('')}<button class="mode-card" data-mode="writing">${icon('pen')}<h3>${tr('Characters & strokes','Иероглифы и черты')}</h3><p>${tr('Watch, trace, then write from memory.','Посмотрите, обведите, напишите по памяти.')}</p></button></div><div class="card section"><h2>${tr('Let the studio choose','Доверьте выбор студии')}</h2><p class="small muted">${recommendation().reasonText}</p>${btn(tr('Start my adaptive session','Начать адаптивное занятие'),'daily','primary')}</div>`;
if(!practice||practice.mode!==route.tab||practice.lesson!==Number(route.id))makePractice(route.tab,Number(route.id));
const p=practice,l=lessonById(p.lesson),item=p.items[p.i];
if(!item)return `<div class="practice-layout">${sessionStrip()}<div class="card" style="text-align:center;padding:45px"><p class="eyebrow">${tr('A SMALL STEP, COMPLETED','ЕЩЁ ОДИН ШАГ СДЕЛАН')}</p><div class="zh big" aria-hidden="true">好</div><h1>${tr('Time to let it settle.','Дайте знаниям уложиться.')}</h1><p>${p.checked?tr(`${p.correct} of ${p.checked} first responses correct.`,`${p.correct} из ${p.checked} первых ответов верны.`):tr(`${p.rated} practice activities recorded.`,`Записано действий практики: ${p.rated}.`)}</p><p class="small muted">${tr('This is a practice result, not a proficiency level. Return later to check what lasts.','Это результат практики, не уровень владения языком. Вернитесь позже и проверьте, что сохранилось.')}</p><div class="row wrap" style="justify-content:center">${session?btn(tr('Next part of my session','Следующая часть занятия'),'session-next','primary'):`<button class="btn primary" data-practice="${p.mode}" data-lesson="${l.id}">${tr('Practice again','Повторить')}</button><a class="btn" href="#analytics">${tr('See my progress','Посмотреть прогресс')}</a>`}</div></div></div>`;
let body='';const m=modes[p.mode];
if(p.mode==='cards')body=`<p class="small muted">${tr('Recall the meaning, pronunciation, and a useful phrase.','Вспомните значение, произношение и полезную фразу.')}</p><div class="zh big" lang="zh-Hans">${esc(item.hanzi)}</div>${p.revealed?`<div class="pinyin">${esc(item.pinyin)} ${speakButton(item.hanzi)}</div><h2 class="m-t">${esc(item[state.settings.lang])}</h2>${item.mnemonic?`<p class="small muted">${text(item.mnemonic)}</p>`:''}<div class="ratings">${[0,1,2,3].map((r)=>`<button data-rate="${r}">${[tr('Again','Ещё раз'),tr('Hard','Трудно'),tr('Good','Помню'),tr('Easy','Легко')][r]}<small>${r===0?tr('10 minutes','10 минут'):tr('in ','через ')+L.review(state.cards[item.id],r).interval+tr(' days',' дн.')}</small></button>`).join('')}</div><p class="tiny muted m-t">${tr('Self-assessment schedules the next review; it does not count as checked accuracy.','Самооценка назначает повторение; она не входит в точность проверенных ответов.')}</p>`:btn(tr('Show the answer','Показать ответ'),'reveal','primary m-t')}`;
else if(p.mode==='recall')body=`<p class="small muted">${tr('Write the Chinese word for:','Напишите по-китайски:')}</p><h2 class="prompt">${esc(item[state.settings.lang])}</h2><div class="controls" style="justify-content:center"><label for="answer-mode">${tr('Answer with','Формат ответа')}</label><select id="answer-mode" ${p.answered?'disabled':''}><option value="hanzi" ${p.answerMode==='hanzi'?'selected':''}>${tr('Chinese characters','Иероглифы')}</option><option value="pinyin" ${p.answerMode==='pinyin'?'selected':''}>${tr('Pinyin with tones','Пиньинь с тонами')}</option></select></div><label for="answer-input">${p.answerMode==='pinyin'?tr('Tone marks or numbers, e.g. nǐ hǎo / ni3 hao3','Знаки или номера тонов: nǐ hǎo / ni3 hao3'):tr('Use your Chinese keyboard / IME','Используйте китайскую клавиатуру / IME')}</label><input id="answer-input" class="answer-input" lang="zh-Hans" autocomplete="off" spellcheck="false" ${p.answered?'disabled':''} value="${esc(p.typed||'')}">${p.answered?feedback(item.hanzi+' · '+item.pinyin,tr('Recall the whole word, including its tone. Valid alternatives can exist; this check uses the taught word.','Вспоминайте слово целиком, включая тон. Возможны другие верные варианты; здесь проверяется изученное слово.')):btn(tr('Check answer','Проверить ответ'),'check','primary')}`;
else if(p.mode==='grammar')body=`<p class="prompt">${text(item.prompt)}</p>${choices(item.choices,p.answered?item.answer:null)}${p.answered?feedback(item.choices[item.answer],bi(item.why)):''}`;
else if(p.mode==='sentence')body=`<p class="small muted">${tr('Tap chunks to build the sentence. Tap a placed chunk to return it.','Нажимайте на части, чтобы собрать фразу. Нажмите на выбранную часть, чтобы вернуть её.')}</p><h2 class="prompt">${esc(item[state.settings.lang])}</h2><div class="tokens" aria-label="${tr('Your sentence','Ваше предложение')}">${p.selected.map(i=>`<button class="token" data-remove-token="${i}" ${p.answered?'disabled':''}>${esc(item.tokens[i])}</button>`).join('')||`<span class="small muted">${tr('Your sentence appears here','Здесь появится ваша фраза')}</span>`}</div><div class="tokens" style="background:none;border:0">${p.tokens.filter(t=>!p.selected.includes(t.i)).map(t=>`<button class="token" data-token="${t.i}" ${p.answered?'disabled':''}>${esc(t.zh)}</button>`).join('')}</div>${p.answered?feedback(item.zh+' · '+item.pinyin,tr('Notice what comes before the verb and what follows it. This activity checks the model word order.','Обратите внимание на слова перед глаголом и после него. Здесь проверяется порядок слов образца.')):`<button class="btn primary" data-action="check" ${p.selected.length!==item.tokens.length?'disabled':''}>${tr('Check order','Проверить порядок')}</button>`}`;
else if(p.mode==='listening')body=`<p class="small muted">${tr('Listen without looking. Choose the meaning you hear.','Послушайте, не подглядывая. Выберите значение услышанного слова.')}</p><button class="btn primary" style="padding:23px;margin:18px" data-action="listen-question">${icon('audio')} ${tr('Play the word','Послушать слово')}</button><p class="tiny muted">${tr('Device-generated Mandarin voice. A Chinese voice must be installed.','Китайский голос устройства. Требуется установленный китайский голос.')}</p><div id="voice-warning"></div>${choices(p.choices.map(v=>v[state.settings.lang]),p.answered?p.choices.findIndex(v=>v.hanzi===item.hanzi):null,!audioHeard)}${p.answered?feedback(item.hanzi+' · '+item.pinyin, item[state.settings.lang]):''}`;
else if(p.mode==='reading')body=`<p class="eyebrow">${tr('READ WITHOUT PINYIN FIRST','СНАЧАЛА ПРОЧИТАЙТЕ БЕЗ ПИНЬИНЯ')}</p><p class="zh" style="text-align:left" lang="zh-Hans">${esc(item.zh)}</p><p class="prompt">${text(item.question)}</p>${choices(item.options.map(bi),p.answered?item.answer:null)}${p.answered?feedback(bi(item.options[item.answer]),item[state.settings.lang])+`<details><summary>${tr('Show pinyin','Показать пиньинь')}</summary><p class="pinyin">${esc(item.pinyin)}</p></details>`:''}`;
else if(p.mode==='speaking')body=`<p class="small muted">${tr('Phrases you rated difficult come first. Listen once, shadow it, then say it with your own meaning.','Сначала идут фразы, которые вы отметили как трудные. Послушайте, повторите вслед за голосом и скажите фразу от себя.')}</p><p class="zh medium" lang="zh-Hans">${esc(item.zh)}</p>${true?`<p class="pinyin">${esc(item.pinyin)}</p>`:''}<p>${esc(item[state.settings.lang])}</p><div class="row wrap" style="justify-content:center"><button class="btn" data-speak="${esc(item.zh)}">${icon('audio')}${tr('Model audio','Образец')}</button><button class="btn primary" data-action="record" id="record-btn">${icon('mic')}${tr('Record myself','Записать себя')}</button><button class="btn" data-action="stop-record" id="stop-record" disabled>${tr('Stop','Стоп')}</button></div><div id="record-area"></div><div class="section-line" style="text-align:left"><h3>${tr('Compare, don’t chase a score.','Сравнивайте по конкретным признакам.')}</h3><ul class="small muted"><li>${tr('Are the tones distinct? Is the third tone low when it should be?','Различаются ли тоны? Низкий ли третий тон там, где нужно?')}</li><li>${tr('Are initials aspirated where needed? Are word boundaries natural?','Есть ли нужное придыхание? Естественны ли границы слов?')}</li><li>${tr('Can you say it again without reading?','Можете повторить, не читая?')}</li></ul><div class="row wrap"><button class="btn" data-speech-rate="1">${tr('Needs practice','Нужно повторить')}</button><button class="btn" data-speech-rate="2">${tr('Comfortable','Уверенно')}</button><button class="btn small ghost" data-action="transcribe">${tr('Optional transcript','Распознать текст')}</button></div><div id="transcript" class="small muted m-t"></div>${l.speakingTask?`<details class="m-t"><summary>${tr('Use it in a real conversation','Примените в разговоре')}</summary><p class="small">${text(l.speakingTask.prompt)}</p><p class="zh">${l.speakingTask.targets.map(esc).join(' · ')}</p><ul class="small">${l.speakingTask.checklist.map(x=>`<li>${text(x)}</li>`).join('')}</ul></details>`:''}<p class="tiny muted">${tr('Recording stays in this tab and is deleted when you leave. Optional speech recognition may send audio to your browser’s provider and requires network support; it is not a pronunciation or tone assessment.','Запись остаётся во вкладке и удаляется при выходе. Необязательное распознавание может отправлять звук провайдеру браузера и требует сети; это не оценка произношения или тонов.')}</p></div>`;
return `<div class="practice-layout">${sessionStrip()}<div class="section-head"><div><p class="eyebrow">${tr('CLASS','УРОК')} ${l.id} · ${tr(m[0],m[1])}</p><h2>${text(l.title)}</h2></div><span class="tag">${p.i+1} / ${p.items.length}</span></div><div class="progress-strip">${p.items.map((_,i)=>`<div class="${i<p.i?'done':''}"></div>`).join('')}</div><div class="practice-card">${body}</div><div class="practice-footer"><a href="#practice" class="small">← ${tr('Practice menu','Меню практики')}</a><span class="tiny muted">${tr('First responses are recorded once. Reveals are not correct answers.','Первый ответ записывается один раз. Просмотр ответа не считается успехом.')}</span>${p.answered?btn(tr('Continue','Далее')+' →','next','primary'):''}</div></div>`;
}
function choices(arr,correctIndex,disabled=false){return `<div class="choices">${arr.map((c,i)=>`<button class="choice ${correctIndex===i?'correct':practice?.answered&&practice.choice===i?'wrong':''}" data-choice="${i}" ${practice?.answered||disabled?'disabled':''}><span class="letter">${String.fromCharCode(65+i)}</span><span>${esc(c)}</span></button>`).join('')}</div>`;}
function feedback(answer,why){return `<div class="answer ${practice.result?'':'incorrect'}" role="status"><h3>${practice.result?tr('That’s right.','Верно.'):tr('A useful correction.','Разберём исправление.')}</h3><div class="zh">${esc(answer)}</div><p class="small no-margin">${esc(why)}</p></div>`;}
function checked(correct,skill){if(practice.answered)return;const item=practice.items[practice.i];practice.result=correct;practice.answered=true;practice.checked++;if(correct)practice.correct++;log({lesson:practice.lesson,item:item.id,skill,kind:'checked',correct});if(skill==='vocabulary'){state.cards[item.id]=L.review(state.cards[item.id],correct?2:0);persist();}render();}
function nextQuestion(){practice.i++;practice.typed='';prepQuestion();render();}
function workbookLesson(id){return C.workbook?.lessons?.find(l=>l.id===Number(id));}
function writingPage(){const l=currentLesson(),w=workbookLesson(l.id),chars=w?.characters||l.characters||['你','好'];if(!chars.includes(writeChar))writeChar=Studio.rankSelf(chars.map(zh=>({id:zh})),'writing')[0].id;return `${title('Let your hand learn, too.','Учитесь и рукой тоже.','Watch the structure. Follow the strokes. Then recall it without a guide.','Рассмотрите структуру. Повторите черты. Затем напишите без образца.')} ${sessionStrip()}<div class="controls"><label for="writing-lesson">${tr('Class','Урок')}</label>${lessonSelect(l.id,'writing-lesson')}<a class="btn small" href="https://www.hanziwu.com/${state.settings.lang==='ru'?'ru':'en'}" target="_blank" rel="noopener">Hanziwu ↗</a></div><div class="char-picker" aria-label="${tr('Target characters','Целевые иероглифы')}">${chars.map(ch=>`<button data-char="${esc(ch)}" class="${ch===writeChar?'active':''}" aria-pressed="${ch===writeChar}" lang="zh-Hans">${esc(ch)}</button>`).join('')}</div><div class="card write-grid"><div><div class="hanzi-stage"><div id="writer"></div><canvas id="draw" width="560" height="560" hidden aria-label="${tr('Freehand writing canvas','Поле для письма от руки')}"></canvas></div><p class="tiny muted" style="text-align:center;margin-top:9px">${tr('Mouse, pen, or touch','Мышь, стилус или касание')}</p></div><div><p class="small muted">${tr('Characters you rated difficult are suggested first.','Сначала предлагаются иероглифы, которые вы отметили как трудные.')}</p><p class="eyebrow">${tr('WATCH → TRACE → RECALL','СМОТРИТЕ → ПОВТОРЯЙТЕ → ВСПОМИНАЙТЕ')}</p><h2><span class="zh medium">${esc(writeChar)}</span> ${characterMeaning(writeChar,l)}</h2><p class="small muted">${tr('Look for meaningful components, then observe the actual stroke order. General rules have exceptions; follow the animation for this character.','Найдите знакомые компоненты, затем проследите реальный порядок черт. У общих правил есть исключения; ориентируйтесь на анимацию конкретного знака.')}</p><div class="row wrap"><button class="btn primary" data-action="animate">${tr('Animate strokes','Порядок черт')}</button><button class="btn" data-action="trace">${tr('Guided practice','Практика с подсказкой')}</button><button class="btn" data-action="freehand">${tr('Write from memory','Написать по памяти')}</button></div><div id="write-status" class="small muted m-t" role="status"></div><div class="row wrap m-t"><button class="btn small" data-action="clear-drawing">${tr('Clear','Очистить')}</button><button class="btn small" data-action="show-character">${tr('Show / hide model','Показать / скрыть образец')}</button><button class="btn small" data-action="save-drawing">${tr('Save my writing','Сохранить написание')}</button></div><p class="tiny muted m-t">${tr('Guided completion and freehand self-assessment are tracked separately from answer accuracy. The canvas cannot judge the quality of freehand writing. Keyboard alternative: write on paper and record your self-assessment below.','Завершение по подсказке и самооценка письма учитываются отдельно от точности ответов. Поле не оценивает качество свободного письма. Вариант без мыши: пишите на бумаге и отметьте самооценку ниже.')}</p><div class="row wrap"><button class="btn" data-write-rate="1">${tr('Need another look','Нужен ещё образец')}</button><button class="btn" data-write-rate="2">${tr('Recalled unaided','Написал по памяти')}</button></div>${session?`<button class="btn primary m-t" data-action="session-next">${tr('Continue my session','Продолжить занятие')} →</button>`:''}</div></div><div class="grid3 section"><div class="card"><h3>${tr('Structure first','Сначала структура')}</h3><p class="small muted">${tr('Is it left–right, top–bottom, or an enclosure? Keep components balanced inside the square.','Это структура слева направо, сверху вниз или рамка? Сохраняйте пропорции внутри квадрата.')}</p></div><div class="card"><h3>${tr('A word, not just a shape','Слово, а не только форма')}</h3><p class="small muted">${tr('Say a word containing the character. Link its form to sound and meaning instead of copying silently.','Произнесите слово с этим иероглифом. Связывайте форму, звук и значение, а не просто копируйте.')}</p></div><div class="card"><h3>${tr('Return after a delay','Вернитесь через время')}</h3><p class="small muted">${tr('After one accurate model and a few attempts, hide the guide. Revisit tomorrow; endless copying is not the goal.','После образца и нескольких попыток уберите подсказку. Вернитесь завтра: цель не в бесконечном копировании.')}</p></div></div>`;}
function characterMeaning(ch,l){const v=l.vocab.find(v=>v.hanzi===ch);return v?`<small class="small muted">${esc(v.pinyin)} · ${esc(v[state.settings.lang])}</small>`:'';}
function mountWriter(){writer=null;drawing=false;drawPoints=[];drawHistory=[];const savedDrawing=state.drawings[writeChar];if(window.HanziWriter&&window.STROKES?.[writeChar]){writer=HanziWriter.create('writer',writeChar,{width:278,height:278,padding:20,strokeColor:'#20594e',radicalColor:'#ad563b',outlineColor:'#dfe5d5',showCharacter:true,showOutline:true,strokeAnimationSpeed:1,delayBetweenStrokes:250,charDataLoader:(char,done)=>done(STROKES[char])});}else{$('#writer').innerHTML=`<div class="zh" style="font-size:185px;text-align:center;line-height:278px">${esc(writeChar)}</div>`;$('#write-status').textContent=tr('Stroke data unavailable for this character. Use freehand and compare with Hanziwu.','Для этого знака нет данных о чертах. Пишите от руки и сравните с Hanziwu.');}
const canvas=$('#draw');if(!canvas)return;const ctx=canvas.getContext('2d');ctx.strokeStyle='#20594e';ctx.lineWidth=9;ctx.lineCap='round';ctx.lineJoin='round';
if(savedDrawing){try{drawHistory=JSON.parse(savedDrawing);if(!Array.isArray(drawHistory))drawHistory=[];}catch{drawHistory=[];}}
const point=e=>{const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)*560/r.width,(e.clientY-r.top)*560/r.height];};
canvas.onpointerdown=e=>{canvas.setPointerCapture(e.pointerId);drawing=true;drawPoints=[point(e)];ctx.beginPath();ctx.moveTo(...drawPoints[0]);e.preventDefault();};
canvas.onpointermove=e=>{if(!drawing)return;const p=point(e);drawPoints.push(p);ctx.lineTo(...p);ctx.stroke();};
canvas.onpointerup=canvas.onpointercancel=()=>{if(drawing&&drawPoints.length)drawHistory.push(drawPoints);drawing=false;};
}
function redraw(){const c=$('#draw'),ctx=c.getContext('2d');ctx.clearRect(0,0,560,560);drawHistory.forEach(points=>{if(!points.length)return;ctx.beginPath();ctx.moveTo(...points[0]);points.slice(1).forEach(p=>ctx.lineTo(...p));ctx.stroke();});}
function writeAction(action){if(action==='animate'){if(!writer)return toast(tr('Use Hanziwu for this character’s stroke order.','Посмотрите порядок черт этого знака в Hanziwu.'));$('#draw').hidden=true;writer.cancelQuiz();writer.showCharacter();writer.animateCharacter();}
if(action==='trace'){if(!writer)return toast(tr('Guided stroke data is unavailable. Use freehand.','Нет данных для проверки черт. Используйте свободное письмо.'));$('#draw').hidden=true;$('#write-status').textContent=tr('Follow the outline. A hint appears after a missed stroke.','Следуйте контуру. После ошибки появится подсказка.');writer.quiz({showHintAfterMisses:1,onComplete:d=>{log({lesson:currentLesson().id,item:writeChar,kind:'writing',skill:'writing',correct:d.totalMistakes===0});$('#write-status').textContent=tr(`Guided practice complete · ${d.totalMistakes} stroke retries. Now try from memory.`,`Практика с подсказкой завершена · повторов черт: ${d.totalMistakes}. Теперь попробуйте по памяти.`);}});}
if(action==='freehand'){writer?.cancelQuiz();if(writer){writer.hideCharacter();writer.hideOutline();}else $('#writer').style.visibility='hidden';$('#draw').hidden=false;redraw();$('#write-status').textContent=tr('Write from memory, reveal the model, then assess your attempt.','Напишите по памяти, откройте образец и оцените попытку.');}
if(action==='clear-drawing'){drawHistory=[];drawPoints=[];redraw();}
if(action==='show-character'){if(writer){if(writeAction.show){writer.hideCharacter();writer.hideOutline();}else{writer.showCharacter();writer.showOutline();}writeAction.show=!writeAction.show;}else $('#writer').style.visibility=$('#writer').style.visibility==='hidden'?'visible':'hidden';}
if(action==='save-drawing'){if(!drawHistory.length)return toast(tr('Write something on the memory canvas first.','Сначала напишите что-нибудь в режиме письма по памяти.'));const value=JSON.stringify(drawHistory);if(value.length>200000)return toast(tr('Drawing is too large. Save fewer strokes.','Рисунок слишком велик. Сохраните меньше черт.'));state.drawings[writeChar]=value;persist();toast(tr('Writing saved in your progress backup.','Написание сохранено в данных прогресса.'));}}
function homeworkPage(){const l=currentLesson(),w=workbookLesson(l.id);if(!w)return title('Homework notebook','Тетрадь домашних заданий','Workbook content is unavailable.','Данные рабочей тетради недоступны.');const groups=w.groups||[],total=groups.reduce((s,g)=>s+(g.items?.length||0),0);return `${title('A place for your homework.','Место для домашних заданий.','Work from your workbook, keep your answers, and learn from corrections.','Работайте с тетрадью, сохраняйте ответы и разбирайте исправления.')}<div class="controls"><label for="homework-lesson">${tr('Class','Урок')}</label>${lessonSelect(l.id,'homework-lesson')}<button class="btn small" data-action="open-workbook" data-page="${w.pdfStart}">${icon('book')}${tr('Open original PDF','Открыть исходный PDF')}</button>${btn(tr('Print notebook','Распечатать тетрадь'),'print','small')}</div><div class="notice">${tr('The supplied workbook has no separate publisher answer key. Answers here are authored model answers checked against the source questions. Open-ended tasks can have other valid answers. Only exact-answer items are automatically scored.','В приложенной тетради нет отдельного ключа издателя. Здесь даны составленные ответы-образцы, сверенные с вопросами. У открытых заданий возможны другие верные ответы. Автоматически проверяются только задания с однозначным ответом.')}</div><div class="card"><div class="row between"><div><p class="eyebrow">${tr('CHARACTER WORKBOOK','ТЕТРАДЬ ИЕРОГЛИФОВ')} · ${l.id}</p><h2>${esc(l.titleZh)} <span class="small muted">${text(l.title)}</span></h2></div><span class="tag">PDF ${w.pdfStart}–${w.pdfEnd}</span></div><p class="small muted">${tr('Printed pages','Печатные страницы')} ${w.printedStart}–${w.printedEnd} · ${groups.length} ${tr('exercise groups','групп заданий')} · ${total} ${tr('digital practice items','цифровых заданий')}</p><p class="zh" lang="zh-Hans">${w.characters.join('　')}</p><a class="btn small" href="#writing/${l.id}">${tr('Practice target characters','Отработать иероглифы')}</a></div>${Studio.homeworkNext(l.id)}<section class="section">${groups.map((g,gi)=>`<article class="card hw-group"><div class="row between"><h2>${gi+1}. ${text(g.title)}</h2><span class="tag">PDF ${(g.pdfPages||[]).join(', ')}</span></div><p class="small muted">${text(g.guide)}</p>${(g.items||[]).map((it,ii)=>homeworkItem(it,l.id,g.id||gi,ii)).join('')}<details><summary>${tr('My notes for the complete source exercise','Мои ответы ко всему упражнению в книге')}</summary><p class="small muted">${tr('Use this notebook for every sub-question on the listed source pages, including diagrams, handwriting, dialogue and longer reading. Your text is saved automatically.','Записывайте сюда ответы на все пункты указанных страниц, включая схемы, письмо, диалоги и длинные тексты. Ответы сохраняются автоматически.')}</p><label for="group-${l.id}-${gi}">${tr('Answers and questions for my teacher','Ответы и вопросы преподавателю')}</label><textarea id="group-${l.id}-${gi}" data-homework-note="group-${l.id}-${gi}">${esc(state.homework[`group-${l.id}-${gi}`]||'')}</textarea></details></article>`).join('')}</section><div class="card"><h3>${tr('My homework reflection','Итог домашнего задания')}</h3><p class="small muted">${tr('Which mistake repeated? Write a corrected sentence and explain what changed.','Какая ошибка повторялась? Напишите исправленную фразу и объясните, что изменилось.')}</p><textarea aria-label="${tr('Homework reflection','Итог задания')}" data-homework-note="reflection-${l.id}">${esc(state.homework['reflection-'+l.id]||'')}</textarea></div>`;}
function homeworkItem(it,lesson,group,ii){const key=it.id||`hw-${lesson}-${group}-${ii}`,value=state.homework[key]||'',last=[...state.events].reverse().find(e=>e.item===key&&e.skill==='homework'),label=it.kind==='open'?tr('Model answer · other answers possible','Образец · возможны другие ответы'):tr('Suggested answer','Предлагаемый ответ');return `<div class="hw-item" id="item-${esc(key)}" data-hw-id="${esc(key)}" data-pinyin-recall="${Studio.isPinyinRecall(it)}"><div class="row between"><h3>${ii+1}. ${text(it.prompt)}</h3><span class="tiny muted">${it.sourcePage?'PDF '+it.sourcePage:''} ${last?last.kind==='checked'?(last.correct?'✓':'↺'):tr('viewed','просмотрено'):''}</span></div>${it.zh?`<p class="zh" lang="zh-Hans">${esc(it.zh)}</p>`:''}${Studio.homeworkHelp(it,lesson)}<label for="hw-${esc(key)}">${tr('My answer','Мой ответ')}</label><textarea id="hw-${esc(key)}" data-hw-input="${esc(key)}" rows="2" style="min-height:60px" lang="zh-Hans">${esc(value)}</textarea><div class="row wrap m-t">${it.kind!=='open'&&it.answers?.length?`<button class="btn small" data-hw-check="${esc(key)}" data-hw-lesson="${lesson}">${tr('Check my first answer','Проверить первый ответ')}</button>`:''}<button class="btn small ghost" data-hw-reveal="${esc(key)}" data-hw-lesson="${lesson}">${tr('Show answer & explanation','Открыть ответ и объяснение')}</button></div><div id="result-${esc(key)}" class="small" role="status"></div><div id="model-${esc(key)}" class="hw-answer" hidden><p class="eyebrow">${label}</p><div class="zh">${esc((it.answers||[]).join(' / ')||bi(it.modelAnswer)||'')}</div><p class="small no-margin">${text(it.explanation)}</p></div></div>`;}
function findHW(id){for(const l of C.workbook?.lessons||[])for(const g of l.groups||[])for(const it of g.items||[])if(it.id===id)return {...it,lesson:l.id};return null;}
function checkHomework(id,reveal=false){const it=findHW(id);if(!it)return;const model=$('#model-'+CSS.escape(id)),result=$('#result-'+CSS.escape(id)),input=$('#hw-'+CSS.escape(id));if(!reveal&&!input.value.trim())return toast(tr('Try an answer first.','Сначала попробуйте ответить.'));const attempted=state.events.some(e=>e.item===id&&e.skill==='homework');model.hidden=false;Studio.annotate(model);
if(reveal){if(!attempted)log({lesson:it.lesson,item:id,skill:'homework',kind:'study',correct:false});result.textContent=tr('Answer revealed. Try again from memory another day.','Ответ открыт. Попробуйте вспомнить его в другой день.');}
else{const correct=L.matches(input.value,it.answers,it.answerMode||(/^[a-zāáǎàēéěèīíǐìōóǒòūúǔùǖǘǚǜü\s1-5'’-]+$/i.test(it.answers[0])?'pinyin':'hanzi'));if(!attempted)log({lesson:it.lesson,item:id,skill:'homework',kind:'checked',correct});result.textContent=(correct?tr('Matches the model answer.','Совпадает с образцом.'):tr('Compare your response with the model below.','Сравните свой ответ с образцом ниже.'))+(attempted?tr(' Practice after a previous attempt or reveal is not scored again.',' Повтор после попытки или подсказки не оценивается заново.'):'');}
}
function analyticsPage(){const checked=L.stats(state.events),self=state.events.filter(e=>e.kind==='self').length,guided=state.events.filter(e=>e.kind==='writing').length,weak=L.weak(state.events),days=Array.from({length:14},(_,i)=>{const d=new Date();d.setDate(d.getDate()-13+i);const events=state.events.filter(e=>L.dateKey(e.at)===L.dateKey(d));return {date:d,count:events.length};}),max=Math.max(1,...days.map(d=>d.count));return `${title('Know what needs your attention.','Узнайте, что стоит повторить.','Evidence from your practice, with the uncertainty left visible.','Данные вашей практики с честным указанием неопределённости.',btn(icon('download')+tr('Export attempts','Экспорт попыток'),'export-csv','small'))}<div class="grid4">${metric(pct(checked.rate),tr('Checked accuracy','Точность проверок'),`n = ${checked.n}`)}${metric(state.events.length,tr('Practice events','Действий практики'),tr('All recorded activity','Все записанные действия'))}${metric(self,tr('Self-assessments','Самооценок'),tr('Separate from accuracy','Не входят в точность'))}${metric(guided,tr('Guided characters','Завершений по контуру'),tr('Completion, not mastery','Завершение, не владение'))}</div><div class="grid2 section"><section class="card"><h2>${tr('Your last two weeks','Последние две недели')}</h2><p class="small muted">${tr('Recorded activities per day. This is engagement, not time spent or fluency.','Действий в день. Это активность, а не время занятий или беглость речи.')}</p><div class="chart-bars" role="img" aria-label="${esc(days.map(d=>date(d.date)+': '+d.count).join('; '))}">${days.map(d=>`<div class="chart-day"><span class="count">${d.count||''}</span><div class="bar" style="height:${Math.max(2,d.count/max*90)}px"></div><span>${d.date.getDate()}</span></div>`).join('')}</div></section><section class="card"><h2>${tr('What to practise next','Что повторить дальше')}</h2><p class="small">${recommendation().reasonText}</p>${btn(tr('Start recommended practice','Начать рекомендованную практику'),'daily','primary')}<p class="stats-note">${tr('Priority: overdue cards → repeatedly difficult checked items → new words in started classes → the next class. At least 3 checks are needed before an error-based recommendation.','Приоритет: повторения → устойчивые ошибки в проверках → новые слова начатых уроков → следующий урок. Рекомендация по ошибке появляется после минимум 3 проверок.')}</p></section></div><section class="card section"><h2>${tr('Skills, with sample size','Навыки и объём данных')}</h2><div class="table-wrap"><table><thead><tr><th>${tr('Skill','Навык')}</th><th>${tr('Correct / attempts','Верно / попыток')}</th><th>${tr('Accuracy','Точность')}</th><th>${tr('95% interval','95% интервал')}</th><th>${tr('Interpretation','Как читать')}</th></tr></thead><tbody>${['vocabulary','grammar','reading','listening','homework','phonetics'].map(k=>{const s=L.stats(state.events,k);return `<tr><td>${skillName(k)}</td><td>${s.k} / ${s.n}</td><td>${pct(s.rate)}</td><td>${s.n?`${Math.round(s.ci[0]*100)}–${Math.round(s.ci[1]*100)}%`:'—'}</td><td>${s.n<5?tr('Not enough evidence','Пока мало данных'):s.n<20?tr('Early signal','Предварительный сигнал'):tr('Practice performance','Результат практики')}</td></tr>`;}).join('')}</tbody></table></div><p class="stats-note">${tr('Wilson intervals describe uncertainty in observed checked responses. Repeated questions are not independent, so these are descriptive indicators, not a test score, predicted retention, or a CEFR/HSK level. Speaking, flashcard ratings and writing quality are self-assessed.','Интервалы Уилсона показывают неопределённость доли проверенных ответов. Повторные задания не независимы: это описательные показатели, не результат экзамена, прогноз памяти или уровень CEFR/HSK. Речь, карточки и качество письма оцениваются самостоятельно.')}</p></section><div class="grid2 section"><section class="card"><h2>${tr('Mistakes worth revisiting','Ошибки, к которым стоит вернуться')}</h2>${weak.length?weak.slice(0,8).map(g=>{const word=allVocab().find(v=>v.id===g.item);return `<div class="resource"><div class="row between"><span>${word?`<span class="zh">${esc(word.hanzi)}</span>`:skillName(g.skill)} <span class="small muted">· ${tr('Class','Урок')} ${g.lesson}</span><button class="btn small" data-practice="${g.skill==='grammar'?'grammar':g.skill==='listening'?'listening':g.skill==='reading'?'reading':'recall'}" data-lesson="${g.lesson||1}">${tr('Revisit','Повторить')}</button></div><span>${g.n-g.k} ${tr('misses across','ошибок из')} ${g.n} ${tr('attempts','попыток')}. ${g.n<3?tr('Small sample; try again before drawing conclusions.','Мало данных; повторите, прежде чем делать выводы.'):tr('Reconstruct the answer before checking the explanation.','Восстановите ответ перед просмотром объяснения.')}</span></div>`;}).join(''):`<div class="empty">${tr('Your checked mistakes will appear here. Start a short practice to collect useful evidence.','Здесь появятся ошибки из проверок. Начните короткую практику, чтобы собрать полезные данные.')}</div>`}</section><section class="card"><h2>${tr('Class by class','По урокам')}</h2><div class="table-wrap"><table><thead><tr><th>${tr('Class','Урок')}</th><th>${tr('Checks','Проверок')}</th><th>${tr('Accuracy','Точность')}</th><th>${tr('Studied','Пройден')}</th></tr></thead><tbody>${C.lessons.map(l=>{const s=L.stats(state.events,null,l.id);return `<tr><td><a href="#lesson/${l.id}">${l.id}. ${text(l.title)}</a></td><td>${s.n}</td><td>${pct(s.rate)}</td><td>${state.completed.includes(l.id)?'✓':'—'}</td></tr>`;}).join('')}</tbody></table></div></section></div><div class="card section"><h3>${tr('How review dates are chosen','Как назначаются повторения')}</h3><p class="small muted">${tr('A transparent interval heuristic starts at 1 day, then 3 days, then grows with successful recall. “Again” returns after 10 minutes; “Hard” grows slowly. This is not FSRS or a validated memory model. Your schedule is per vocabulary card and does not pretend that recognizing a word proves listening or speaking ability.','Простая эвристика начинает с 1 дня, затем 3 дней и увеличивает интервал после успешного воспроизведения. «Ещё раз» возвращает карточку через 10 минут; «Трудно» увеличивает интервал медленно. Это не FSRS и не валидированная модель памяти. Расписание относится к карточке слова и не означает, что узнавание доказывает умение слушать или говорить.')}</p></div>`;}
function libraryPage(){return `${title('The books behind your practice.','Книги и материалы для практики.','Source maps, learning evidence, and a private place to open your PDFs.','Карта источников, исследования и локальное открытие ваших PDF.')}<div class="card"><h2>${tr('Open your original books locally','Откройте исходные книги локально')}</h2><p class="small muted">${tr('Select the full Desktop workbook (280 pages) or Book I (314 pages). The 10-page Downloads excerpt is a different file. PDFs stay in this browser; they are not uploaded or included in the public website. Browser storage may be cleared, so keep your originals.','Выберите полную тетрадь с рабочего стола (280 страниц) или Book I (314 страниц). 10-страничный файл из Downloads — отдельная выдержка. PDF остаются в браузере; они не загружаются на сервер и не включены в публичный сайт. Хранилище браузера может очищаться: сохраняйте оригиналы.')}</p><div class="controls"><label for="book-kind">${tr('Document','Документ')}</label><select id="book-kind"><option value="workbook" ${bookKind==='workbook'?'selected':''}>${tr('Character workbook · 280 pages','Тетрадь иероглифов · 280 страниц')}</option><option value="textbook" ${bookKind==='textbook'?'selected':''}>Hello Chinese I · 314</option><option value="excerpt" ${bookKind==='excerpt'?'selected':''}>${tr('Lesson 1 excerpt · 10 pages','Выдержка урока 1 · 10 страниц')}</option><option value="grammar" ${bookKind==='grammar'?'selected':''}>${tr('Grammar notes · 27 pages','Грамматический конспект · 27 страниц')}</option></select><label class="btn small" for="pdf-input">${tr('Choose local PDF','Выбрать локальный PDF')}</label><input type="file" id="pdf-input" accept="application/pdf,.pdf" class="visually-hidden"></div><div class="book-tools"><label for="book-page">${tr('PDF page','Страница PDF')}</label><input type="number" id="book-page" value="${bookPage}" min="1" max="${bookKind==='workbook'?280:bookKind==='textbook'?314:bookKind==='excerpt'?10:27}"><button class="btn small" data-action="book-page">${tr('Go to page','Перейти')}</button><button class="btn small" data-action="load-pdf">${tr('Restore saved PDF','Открыть сохранённый PDF')}</button></div><div id="pdf-area">${bookUrl?'<div id="book-mount"></div>':`<div class="empty">${tr('No PDF opened. Your digital exercises and model answers work independently; items that depend on an illustration or full passage are marked.','PDF ещё не открыт. Цифровые задания и ответы работают отдельно; задания, требующие рисунка или полного текста, отмечены.')}</div>`}</div><div id="pdf-status" class="tiny muted m-t" role="status"></div></div><section class="card section"><h2>${tr('Find the right pages','Найдите нужные страницы')}</h2><div class="table-wrap"><table><thead><tr><th>${tr('Class','Урок')}</th><th>${tr('Book I · PDF','Book I · PDF')}</th><th>${tr('Workbook · PDF','Тетрадь · PDF')}</th><th>${tr('Focus','Тема')}</th></tr></thead><tbody>${C.bookMap.map(b=>{const w=workbookLesson(b.lesson);return `<tr><td>${b.lesson}</td><td><button class="btn small ghost" data-open-book="textbook" data-page="${b.pdfStart}">${b.pdfStart}–${b.pdfEnd}</button></td><td>${w?`<button class="btn small ghost" data-open-book="workbook" data-page="${w.pdfStart}">${w.pdfStart}–${w.pdfEnd}</button>`:'258–275'}</td><td>${b.lesson<=14?text(lessonById(b.lesson).title):tr('Extension: booking a flight','Продолжение: бронирование билета')}</td></tr>`;}).join('')}</tbody></table></div><p class="small muted m-t">${tr('Book I: listening scripts PDF 309–311; sentence examples PDF 312–314. Workbook: Reviews 1/2 PDF 90–96 / 184–190; Review 3 PDF 276–280. Workbook lesson 13 starts at PDF 224, despite a contents-page typo.','Book I: тексты аудирования PDF 309–311; примеры предложений PDF 312–314. Тетрадь: повторения 1/2 — PDF 90–96 / 184–190; повторение 3 — PDF 276–280. Урок 13 тетради начинается с PDF 224, несмотря на опечатку в оглавлении.')}</p><div class="row wrap"><a class="btn small" href="docs/ANALYSIS.html" target="_blank">${tr('Read the full source analysis','Прочитать полный анализ')} ↗</a><a class="btn small" href="docs/BOOK-ANALYSIS.md" target="_blank">${tr('Detailed textbook audit','Подробный аудит учебника')}</a></div></section><section class="section"><h2>${tr('Why these learning methods','Почему именно эти методы')}</h2><div class="grid2">${(C.research?.methods||[]).map(m=>`<article class="card"><h3>${text(m.title)}</h3><p class="small">${text(m.finding)}</p><p class="small muted">${text(m.design)}</p><div class="tip">${text(m.limits)}</div><div class="small m-t">${(m.sources||[]).map(id=>{const src=C.research.sources.find(s=>s.id===id);return src?link(esc(typeof src.title==='string'?src.title:bi(src.title)),src.url):'';}).join(' · ')}</div></article>`).join('')}</div></section><section class="card section"><h2>${tr('Textbook listening answer companion','Ответы к аудированию учебника')}</h2><p class="small muted">${tr('Use the source exercises and appendix scripts. These are editor-derived models, not a publisher key. Some source questions are ambiguous; read the explanation. Original recorded audio is not bundled.','Используйте задания и тексты аудирования в приложении книги. Это редакторские образцы, не ключ издателя. Некоторые вопросы неоднозначны: читайте пояснение. Исходные аудиозаписи не включены.')}</p>${(C.listening?.lessons||[]).map(l=>`<details><summary>${tr('Class','Урок')} ${l.lesson} · ${tr('exercise','задание')} PDF ${l.exercisePdf.join(', ')} · ${tr('script','текст')} PDF ${l.transcriptPdf.join(', ')}</summary>${l.items.map(it=>`<div class="example"><span class="small">${it.n}. </span><span class="zh">${esc(typeof it.answer==='boolean'?(it.answer?'✓':'✗'):it.answer)}</span><p class="small muted">${esc(it[state.settings.lang])}</p>${it.automaticGrade===false?`<span class="tag coral">${tr('Ambiguous source item','Неоднозначное задание')}</span>`:''}</div>`).join('')}</details>`).join('')}</section><div class="card section"><h2>${tr('Privacy & availability','Приватность и доступность')}</h2><p class="small muted">${tr('No account, tracking service, API key, or paid backend is required. Progress uses localStorage, optional PDFs use IndexedDB, and voice recording uses a temporary local blob. Export progress to move between devices. Audio depends on installed Mandarin voices and browser permissions. External courses and optional recognition need an internet connection.','Не нужны аккаунт, аналитический сервис, API-ключ или платный сервер. Прогресс хранится в localStorage, PDF — в IndexedDB, запись голоса — временно во вкладке. Для переноса на другое устройство экспортируйте данные. Аудио зависит от установленных китайских голосов и разрешений браузера. Внешние курсы и необязательное распознавание требуют интернета.')}</p><a href="assets/licenses/ARPHICPL.TXT" class="small">Hanzi Writer data · Arphic Public License</a> · <a href="assets/licenses/HANZI-WRITER-MIT.txt" class="small">Hanzi Writer · MIT</a></div>`;}
let pendingImport=null;
function settingsPage(){return `${title('Make the studio yours.','Настройте студию под себя.','A calm pace, the right support, and a copy of your progress.','Удобный темп, нужные подсказки и резервная копия прогресса.')}<div class="grid2"><section class="card"><h2>${tr('Study preferences','Учебные настройки')}</h2><div class="field"><label for="goal-setting">${tr('Daily session target','Ориентир длительности занятия')}</label><select id="goal-setting">${[5,10,15,25].map(n=>`<option value="${n}" ${n===state.settings.goal?'selected':''}>${n} ${tr('minutes','минут')}</option>`).join('')}</select><p class="tiny muted m-t">${tr('Changes the activity count. Actual time varies; the app does not claim to measure study time.','Меняет число заданий. Реальное время отличается; приложение не измеряет время учёбы.')}</p></div><div class="field"><label class="toggle"><input type="checkbox" id="pinyin-setting" ${true?'checked':''}>${tr('Show extra pinyin on vocabulary cards','Дополнительный пиньинь на карточках слов')}</label></div><div class="field"><label for="rate-setting">${tr('Model speech speed','Скорость голоса-образца')}</label><select id="rate-setting">${[.6,.8,1].map(n=>`<option value="${n}" ${n===state.settings.rate?'selected':''}>${n}×</option>`).join('')}</select></div><p class="small muted">${text(C.pinyinPolicy)}</p><p id="voices-status" class="small muted"></p></section><section class="card"><h2>${tr('Keep a backup','Сохраните резервную копию')}</h2><p class="small muted">${tr('Progress is tied to this browser and website address. Clearing site data removes it. Export regularly, and before changing the GitHub repository name or domain. Backups contain your answers and writing, but not PDFs or voice recordings.','Прогресс привязан к браузеру и адресу сайта. Очистка данных сайта удалит его. Экспортируйте регулярно и перед сменой имени репозитория или домена. Копия включает ответы и рисунки, но не PDF и голосовые записи.')}</p>${btn(icon('download')+tr('Export progress JSON','Экспорт прогресса JSON'),'export','primary')}<div class="section-line"><label class="btn" for="import-input">${tr('Choose a progress backup','Выбрать копию прогресса')}</label><input type="file" id="import-input" accept="application/json,.json" class="visually-hidden"><div id="import-preview" class="small m-t"></div></div></section></div><section class="danger-zone section"><h3>${tr('Reset this browser’s progress','Сбросить прогресс в этом браузере')}</h3><p class="small muted">${tr('Export first. Reset clears cards, results, notes, homework, and saved writing. Locally opened PDFs are stored separately.','Сначала сделайте экспорт. Сброс удаляет карточки, результаты, заметки, задания и написания. Локальные PDF хранятся отдельно.')}</p>${btn(tr('Reset…','Сбросить…'),'reset-start','danger')}<div id="reset-confirm" class="m-t" hidden><p class="small">${tr('This removes all progress in this browser. Do you have a backup?','Это удалит весь прогресс в этом браузере. Резервная копия уже есть?')}</p>${btn(tr('Yes, reset my progress','Да, сбросить прогресс'),'reset-confirm','danger')} ${btn(tr('Cancel','Отмена'),'reset-cancel')}</div></section>`;}
let phoneticIndex=0,phoneticAnswered=false;
function phoneticsPage(){const p=C.phonetics,quiz=p.questions||p.quiz||[];phoneticIndex=Math.min(phoneticIndex,Math.max(0,quiz.length-1));const q=quiz[phoneticIndex];return `${title('Start by listening closely.','Начните с внимательного слушания.','Pinyin describes Mandarin sounds. Tones carry meaning.','Пиньинь описывает звуки путунхуа. Тоны передают смысл.')}<div class="tone-chart">${[['妈','mā','M10 15 L90 15',tr('High and level','Высоко и ровно')],['麻','má','M10 50 L90 8',tr('Rising','Повышение')],['马','mǎ','M10 30 Q45 70 55 48 L90 18',tr('Low / dipping','Низкий / изгиб')],['骂','mà','M10 8 L90 55',tr('Falling','Падение')]].map(([zh,py,path,label],i)=>`<div class="tone"><p class="eyebrow">${tr('TONE','ТОН')} ${i+1}</p><svg viewBox="0 0 100 65" role="img" aria-label="${label}"><path d="${path}" fill="none" stroke="${['#477e75','#ac7e3b','#526e94','#ad563b'][i]}" stroke-width="3" stroke-linecap="round"/></svg><span class="zh">${zh}</span><span class="pinyin"> ${py}</span>${speakButton(zh)}<p>${label}</p></div>`).join('')}</div><div class="notice">${tr('The third-tone curve is an isolated teaching model. In connected speech it is often low without a full rise. Device-generated audio is useful practice; compare with the native companion-course recordings too.','Контур третьего тона — учебная модель отдельного слога. В связной речи он часто низкий без полного подъёма. Синтезированный голос полезен для практики; сравнивайте и с записями носителей из сопутствующего курса.')}</div><div class="stack">${p.sections.map(s=>`<article class="card"><p class="eyebrow">${tr('SOURCE SLIDES','СЛАЙДЫ ИСТОЧНИКА')} ${s.slides.join(', ')}</p><h2>${text(s.title)}</h2><div class="pattern">${(s.inventory||[]).map(esc).join(' · ')}</div><p>${text(s.explanation)}</p><div class="tip">${text(s.tip)}</div><div class="pinyin m-t">${(s.examples||[]).map(esc).join('　 /　 ')}</div></article>`).join('')}</div>${q?`<section class="card section"><div class="row between"><h2>${tr('Check one detail','Проверьте одну деталь')}</h2><span class="tag">${phoneticIndex+1} / ${quiz.length}</span></div><p>${text(q.prompt)}</p><label for="phonetic-answer">${tr('My answer','Мой ответ')}</label><input id="phonetic-answer" type="text" autocomplete="off"><div class="row wrap m-t">${btn(tr('Check','Проверить'),'phonetic-check','primary')}${btn(tr('Next question','Следующий вопрос'),'phonetic-next')}</div><div id="phonetic-feedback" class="small m-t" role="status"></div></section>`:''}<div class="card section"><h2>${tr('Hear people, not just devices','Слушайте и живую речь')}</h2><p class="small muted">${text(p.practiceProtocol)}</p><a class="btn" href="https://www.coursera.org/learn/mandarin-chinese-1" target="_blank" rel="noopener">${tr('SJTU · textbook companion course','SJTU · видеокурс авторов учебника')} ↗</a><p class="tiny muted m-t">${tr('Enrollment may be required. Some content may be paid.','Может понадобиться регистрация. Часть материалов может быть платной.')}</p><a class="btn primary" href="#lesson/1">${tr('Continue to class 1','Перейти к уроку 1')} →</a></div>`;}
function updateVoices(){voiceList='speechSynthesis'in window?speechSynthesis.getVoices().filter(v=>/^zh(?:[-_](?:CN|TW|Hans|Hant))?$/i.test(v.lang)):[];const s=$('#voices-status');if(s)s.textContent=voiceList.length?tr(`Mandarin voices available: ${voiceList.map(v=>v.name).join(', ')}.`,`Доступные китайские голоса: ${voiceList.map(v=>v.name).join(', ')}.`):tr('No Mandarin voice detected. Install Chinese speech in your operating system and restart the browser, or use the linked companion-course recordings.','Китайский голос не найден. Установите китайскую речь в системе и перезапустите браузер либо используйте записи сопутствующего курса.');}
function speak(zh,onEnd){updateVoices();if(!('speechSynthesis'in window)||!voiceList.length){const msg=tr('No Mandarin voice is available. Install a Chinese speech voice in system settings, or use the companion course in lesson resources.','Китайский голос недоступен. Установите его в настройках системы или откройте сопутствующий курс в материалах урока.');toast(msg);if($('#voice-warning'))$('#voice-warning').textContent=msg;return false;}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(zh);utterance.voice=voiceList.find(v=>/CN/i.test(v.lang))||voiceList[0];utterance.lang=utterance.voice.lang;utterance.rate=state.settings.rate;utterance.onend=()=>{if(onEnd)onEnd();};utterance.onerror=e=>{if(e.error!=='interrupted'&&e.error!=='canceled')toast(tr('Audio could not play. Try a different browser or a companion-course recording.','Не удалось воспроизвести звук. Попробуйте другой браузер или запись курса.'));};speechSynthesis.speak(utterance);return true;}
async function record(){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)return toast(tr('Recording is unavailable here. Use HTTPS or localhost and a modern browser; you can also record in your phone’s recorder.','Запись здесь недоступна. Используйте HTTPS или localhost и современный браузер; можно записать речь диктофоном телефона.'));try{stream=await navigator.mediaDevices.getUserMedia({audio:true});if(route.page!=='practice'||practice?.mode!=='speaking'){stream.getTracks().forEach(t=>t.stop());stream=null;return;}let chunks=[];recorder=new MediaRecorder(stream);const activeRecorder=recorder;recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=()=>{stream?.getTracks().forEach(t=>t.stop());stream=null;const area=$('#record-area');if(!area||!chunks.length)return;if(recordUrl)URL.revokeObjectURL(recordUrl);recordUrl=URL.createObjectURL(new Blob(chunks,{type:activeRecorder.mimeType}));area.innerHTML=`<audio controls src="${recordUrl}" aria-label="${tr('Your recording','Ваша запись')}"></audio><p class="tiny muted">${tr('Listen to your recording, then compare with the model.','Прослушайте запись и сравните с образцом.')}</p>`;$('#record-btn')?.classList.remove('recording');if($('#record-btn'))$('#record-btn').disabled=false;if($('#stop-record'))$('#stop-record').disabled=true;};recorder.start();$('#record-btn').disabled=true;$('#record-btn').classList.add('recording');$('#stop-record').disabled=false;$('#record-area').innerHTML=`<p class="recording small" role="status">${tr('Recording… maximum 60 seconds','Идёт запись… максимум 60 секунд')}</p>`;clearTimeout(record.timer);record.timer=setTimeout(()=>{if(recorder?.state==='recording')recorder.stop();},60000);}catch(e){toast(tr('Microphone access was not available. Allow access in browser settings, or practise aloud and self-assess.','Нет доступа к микрофону. Разрешите его в браузере либо проговорите фразу и оцените себя.'));stream?.getTracks().forEach(t=>t.stop());stream=null;}}
function stopCapture(){clearTimeout(record.timer);if(recorder&&recorder.state==='recording'){recorder.onstop=null;recorder.stop();}stream?.getTracks().forEach(t=>t.stop());stream=null;recorder=null;if(recordUrl){URL.revokeObjectURL(recordUrl);recordUrl=null;}if(recognizer){recognizer.abort();recognizer=null;}}
function transcribe(){const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SpeechRecognition)return toast(tr('Speech recognition is not supported here. Use recording and self-comparison.','Распознавание не поддерживается. Используйте запись и самостоятельное сравнение.'));recognizer=new SpeechRecognition();recognizer.lang='zh-CN';recognizer.interimResults=false;recognizer.maxAlternatives=1;const box=$('#transcript');box.textContent=tr('Listening for a transcript…','Слушаю для распознавания…');recognizer.onresult=e=>{if($('#transcript'))$('#transcript').textContent=tr('The browser heard: ','Браузер распознал: ')+e.results[0][0].transcript+tr(' — this does not assess tones or pronunciation.',' — это не оценка тонов или произношения.');};recognizer.onerror=()=>{if($('#transcript'))$('#transcript').textContent=tr('Recognition unavailable or no speech heard. Your recording and self-assessment still work.','Распознавание недоступно или речь не услышана. Запись и самооценка остаются доступны.');};try{recognizer.start();}catch{toast(tr('Recognition could not start.','Не удалось начать распознавание.'));}}
function download(name,data,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportProgress(){download(`zhujian-progress-${L.dateKey()}.json`,JSON.stringify(state,null,2));}
function exportCSV(){const columns=['timestamp','lesson','skill','item','evidence_type','correct','self_rating'];const quote=x=>{let s=String(x??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};download('zhujian-attempts.csv','\ufeff'+[columns,...state.events.map(e=>[new Date(e.at).toISOString(),e.lesson,e.skill,e.item,e.kind,e.kind==='checked'?e.correct:'',e.kind==='self'?e.rating:''])].map(r=>r.map(quote).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
async function openDB(){if(db)return db;return new Promise((resolve,reject)=>{const req=indexedDB.open('zhujian-local-books',1);req.onupgradeneeded=()=>req.result.createObjectStore('books');req.onsuccess=()=>{db=req.result;resolve(db);};req.onerror=()=>reject(req.error);});}
async function loadPDF(){try{const d=await openDB(),value=await new Promise((resolve,reject)=>{const req=d.transaction('books').objectStore('books').get(bookKind);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});if(!value){toast(tr('Choose this PDF from your device first.','Сначала выберите этот PDF на устройстве.'));return;}if(bookUrl)URL.revokeObjectURL(bookUrl);bookUrl=URL.createObjectURL(value);if(route.page==='library'){const area=$('#pdf-area');area.innerHTML='<div id="book-mount"></div>';mountBook();}}catch{toast(tr('Local PDF storage is unavailable. You can still choose a PDF for this session.','Локальное хранилище PDF недоступно. Можно выбрать файл на это занятие.'));}}
function mountBook(){const mount=$('#book-mount')||$('#pdf-area');if(!mount||!bookUrl)return;mount.innerHTML=`<iframe class="book-viewer" title="${tr('Local source PDF','Локальный исходный PDF')}" src="${bookUrl}#page=${bookPage}&view=FitH"></iframe><p class="small"><a href="${bookUrl}#page=${bookPage}" target="_blank" rel="noopener">${tr('Open PDF in a separate tab if the embedded viewer is unavailable','Если встроенный просмотр недоступен, откройте PDF в отдельной вкладке')} ↗</a></p>`;}
async function importPDF(file){if(!file)return;if(file.size>90*1024*1024)return toast(tr('Choose a PDF smaller than 90 MB.','Выберите PDF меньше 90 МБ.'));const header=await file.slice(0,5).text();if(header!=='%PDF-')return toast(tr('This is not a PDF file.','Это не PDF-файл.'));if(bookUrl)URL.revokeObjectURL(bookUrl);bookUrl=URL.createObjectURL(file);mountBook();try{const d=await openDB();await new Promise((resolve,reject)=>{const tx=d.transaction('books','readwrite');tx.objectStore('books').put(file,bookKind);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});$('#pdf-status').textContent=tr('Saved locally. Choose “Restore saved PDF” on a later visit. Page references assume the supplied edition.','Сохранено локально. При следующем посещении нажмите «Открыть сохранённый PDF». Ссылки на страницы относятся к приложенному изданию.');}catch{$('#pdf-status').textContent=tr('Opened for this session. Persistent PDF storage was unavailable.','Открыто на это занятие. Постоянное хранение PDF недоступно.');}}
async function openBook(kind,page){bookKind=kind;bookPage=page;if(bookUrl){URL.revokeObjectURL(bookUrl);bookUrl=null;}if(route.page!=='library'){nav('#library');setTimeout(loadPDF,30);}else{render();await loadPDF();}}
document.addEventListener('click',async e=>{const el=e.target.closest('button,a,label');if(!el)return;const d=el.dataset;
if(d.go){nav(d.go);return;}if(d.lang){state.settings.lang=d.lang;persist();render();return;}if(d.speak){speak(d.speak);return;}
if(d.complete){const id=Number(d.complete);state.completed=state.completed.includes(id)?state.completed.filter(n=>n!==id):[...state.completed,id];persist();render();return;}
if(d.practice){startPractice(d.practice,Number(d.lesson));return;}if(d.mode){const id=Number($('#practice-lesson').value);if(d.mode==='writing'){session=null;nav('#writing/'+id);}else startPractice(d.mode,id);return;}
if(d.rate!==undefined&&practice&&!practice.answered){const item=practice.items[practice.i],r=Number(d.rate);state.cards[item.id]=L.review(state.cards[item.id],r);practice.rated++;log({lesson:practice.lesson,item:item.id,skill:'vocabulary',kind:'self',rating:r});nextQuestion();return;}
if(d.choice!==undefined&&practice&&!practice.answered){const i=Number(d.choice),item=practice.items[practice.i];practice.choice=i;if(practice.mode==='listening'&&!audioHeard)return;checked(practice.mode==='listening'?practice.choices[i].hanzi===item.hanzi:i===item.answer,practice.mode==='grammar'?'grammar':practice.mode);return;}
if(d.token!==undefined&&!practice.answered){practice.selected.push(Number(d.token));render();return;}if(d.removeToken!==undefined&&!practice.answered){practice.selected=practice.selected.filter(n=>n!==Number(d.removeToken));render();return;}
if(d.speechRate){const item=practice.items[practice.i];practice.rated++;log({lesson:practice.lesson,item:item.id,skill:'speaking',kind:'self',rating:Number(d.speechRate)});nextQuestion();return;}
if(d.char){writeChar=d.char;render();return;}if(d.writeRate){log({lesson:currentLesson().id,item:writeChar,kind:'self',skill:'writing',rating:Number(d.writeRate)});toast(tr('Self-assessment saved.','Самооценка сохранена.'));return;}
if(d.hwCheck){checkHomework(d.hwCheck);return;}if(d.hwReveal){checkHomework(d.hwReveal,true);return;}if(d.openBook){await openBook(d.openBook,Number(d.page));return;}
switch(d.action){case'daily':daily();break;case'reveal':practice.revealed=true;render();break;case'next':nextQuestion();break;case'session-next':advanceSession();break;case'check':{const item=practice.items[practice.i];if(practice.mode==='recall'){const value=$('#answer-input').value;if(!value.trim())return toast(tr('Try an answer first.','Сначала попробуйте ответить.'));practice.typed=value;checked(L.matches(value,[practice.answerMode==='pinyin'?item.pinyin:item.hanzi],practice.answerMode),'vocabulary');}else if(practice.mode==='sentence')checked(L.normalize(practice.selected.map(i=>item.tokens[i]).join(''))===L.normalize(item.zh),'grammar');break;}case'listen-question':speak(practice.items[practice.i].hanzi,()=>{if(practice?.mode==='listening'){audioHeard=true;$$('[data-choice]').forEach(b=>b.disabled=false);}});break;case'record':record();break;case'stop-record':if(recorder?.state==='recording')recorder.stop();break;case'transcribe':transcribe();break;case'animate':case'trace':case'freehand':case'clear-drawing':case'show-character':case'save-drawing':writeAction(d.action);break;case'print':window.print();break;case'open-workbook':openBook('workbook',Number(d.page));break;case'book-page':{const n=Number($('#book-page').value);bookPage=Math.max(1,Math.min(n||1,bookKind==='workbook'?280:bookKind==='textbook'?314:bookKind==='excerpt'?10:27));mountBook();break;}case'load-pdf':loadPDF();break;case'export':exportProgress();break;case'export-csv':exportCSV();break;case'import-confirm':if(pendingImport){state=pendingImport;pendingImport=null;persist();render();toast(tr('Progress restored.','Прогресс восстановлен.'));}break;case'reset-start':$('#reset-confirm').hidden=false;break;case'reset-cancel':$('#reset-confirm').hidden=true;break;case'reset-confirm':{const lang=state.settings.lang;state=L.fresh();state.settings.lang=lang;session=null;persist();render();toast(tr('Progress reset.','Прогресс сброшен.'));break;}case'phonetic-check':{const quiz=C.phonetics.questions||C.phonetics.quiz,q=quiz[phoneticIndex],value=$('#phonetic-answer').value;if(!value.trim())return;const ok=L.matches(value,q.answers);if(!phoneticAnswered)log({lesson:0,item:q.id,kind:q.kind==='open'?'self':'checked',skill:'phonetics',correct:ok});phoneticAnswered=true;$('#phonetic-feedback').textContent=(ok?tr('Correct. ','Верно. '):tr('Model answer: ','Образец: '))+q.answers.join(' / ');break;}case'phonetic-next':phoneticIndex=(phoneticIndex+1)%(C.phonetics.questions||C.phonetics.quiz).length;phoneticAnswered=false;render();break;}
});
document.addEventListener('input',e=>{const d=e.target.dataset;if(d.note){state.notes[d.note]=e.target.value;persist();}if(d.homeworkNote||d.hwInput){state.homework[d.homeworkNote||d.hwInput]=e.target.value;persist();}});
document.addEventListener('change',async e=>{const el=e.target;switch(el.id){case'answer-mode':practice.answerMode=el.value;practice.typed='';render();break;case'writing-lesson':writeChar='';session=null;nav('#writing/'+el.value);break;case'homework-lesson':nav('#homework/'+el.value);break;case'goal-setting':state.settings.goal=Number(el.value);persist();break;case'pinyin-setting':state.settings.pinyin=el.checked;persist();break;case'rate-setting':state.settings.rate=Number(el.value);persist();break;case'book-kind':bookKind=el.value;bookPage=1;if(bookUrl){URL.revokeObjectURL(bookUrl);bookUrl=null;}render();break;case'pdf-input':await importPDF(el.files[0]);break;case'import-input':{const file=el.files[0];if(!file)return;if(file.size>12*1024*1024)return toast(tr('Backup is too large (maximum 12 MB).','Копия слишком велика (максимум 12 МБ).'));try{pendingImport=L.validate(JSON.parse(await file.text()));$('#import-preview').innerHTML=`<p>${tr('This will replace the current progress with','Текущий прогресс будет заменён на')} ${pendingImport.events.length} ${tr('events and','действий и')} ${pendingImport.started.length} ${tr('started classes. Export your current progress first if needed.','начатых уроков. При необходимости сначала экспортируйте текущие данные.')}</p>${btn(tr('Restore this backup','Восстановить эту копию'),'import-confirm','primary')}`;}catch{pendingImport=null;toast(tr('Invalid or incompatible progress file. Nothing changed.','Некорректная или несовместимая копия. Данные не изменены.'));}break;}}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='answer-input'&&!practice?.answered){e.preventDefault();$('[data-action="check"]')?.click();}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);$('#main')?.focus({preventScroll:true});});
window.addEventListener('beforeunload',()=>{stopCapture();if(bookUrl)URL.revokeObjectURL(bookUrl);});
if('speechSynthesis'in window)speechSynthesis.addEventListener('voiceschanged',updateVoices);
if('serviceWorker'in navigator&&['http:','https:'].includes(location.protocol))navigator.serviceWorker.register('./sw.js').catch(()=>{});
Studio.init({C,state:()=>state,tr,bi,esc,log,persist,speak,speakButton,toast,nav});
render();if(initialLoadError)toast(tr('Saved data could not be loaded. Import a backup in Settings; the old stored data has not been overwritten.','Не удалось загрузить сохранённые данные. Импортируйте копию в настройках; старые данные ещё не перезаписаны.'));
})();
